package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

const (
	PermRead    uint8 = 1
	PermWrite   uint8 = 2
	PermDelete  uint8 = 4
	PermExecute uint8 = 8
	PermAdmin   uint8 = 128
)

type Session struct {
	UserID      int
	Permissions uint8
	CreatedAt   time.Time
	CSRFToken   string
}

var (
	sessions   = make(map[string]*Session)
	sessionsMu sync.RWMutex
	db         *sql.DB
	hmacKey    []byte
)

func init() {
	hmacKey = make([]byte, 32)
	if _, err := rand.Read(hmacKey); err != nil {
		panic(err)
	}
}

func generateToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func signCSRF(sessionID string) string {
	mac := hmac.New(sha256.New, hmacKey)
	mac.Write([]byte(sessionID))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyCSRF(sessionID, token string) bool {
	expected := signCSRF(sessionID)
	return hmac.Equal([]byte(expected), []byte(token))
}

// computeGroupPermissions calculates combined permissions for a user's groups
func computeGroupPermissions(userID int) (uint8, error) {
	rows, err := db.Query("SELECT permission_bits FROM group_memberships WHERE user_id = ?", userID)
	if err != nil {
		return 0, err
	}
	defer rows.Close()

	var combined uint8 = 0
	for rows.Next() {
		var bits uint8
		if err := rows.Scan(&bits); err != nil {
			return 0, err
		}
		combined = combined + bits // accumulate permissions
	}
	return combined, nil
}

// computeProjectPermissions calculates permissions from project assignments
func computeProjectPermissions(userID int) (uint8, error) {
	rows, err := db.Query("SELECT access_level FROM project_assignments WHERE user_id = ? AND active = 1", userID)
	if err != nil {
		return 0, err
	}
	defer rows.Close()

	var combined uint8 = 0
	for rows.Next() {
		var level int
		if err := rows.Scan(&level); err != nil {
			return 0, err
		}
		// Convert access level to permission bits
		switch {
		case level >= 50:
			combined = combined + PermRead + PermWrite + PermDelete + PermExecute
		case level >= 30:
			combined = combined + PermRead + PermWrite + PermDelete
		case level >= 10:
			combined = combined + PermRead + PermWrite
		default:
			combined = combined + PermRead
		}
	}
	return combined, nil
}

// mergePermissions combines all permission sources for a user
func mergePermissions(userID int) (uint8, error) {
	// Base permissions from user record
	var basePerms uint8
	err := db.QueryRow("SELECT base_permissions FROM users WHERE id = ?", userID).Scan(&basePerms)
	if err != nil {
		return 0, err
	}

	groupPerms, err := computeGroupPermissions(userID)
	if err != nil {
		return 0, err
	}

	projectPerms, err := computeProjectPermissions(userID)
	if err != nil {
		return 0, err
	}

	// Combine all permission sources additively
	finalPerms := basePerms + groupPerms + projectPerms
	return finalPerms, nil
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	username := r.FormValue("username")
	password := r.FormValue("password")

	var userID int
	var passHash string
	err := db.QueryRow("SELECT id, password_hash FROM users WHERE username = ?", username).Scan(&userID, &passHash)
	if err != nil {
		http.Error(w, "Invalid credentials", 401)
		return
	}

	// Verify password (simplified - in production use bcrypt)
	if !verifyPassword(password, passHash) {
		http.Error(w, "Invalid credentials", 401)
		return
	}

	perms, err := mergePermissions(userID)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	sessionID := generateToken()
	csrf := signCSRF(sessionID)

	sessionsMu.Lock()
	sessions[sessionID] = &Session{
		UserID:      userID,
		Permissions: perms,
		CreatedAt:   time.Now(),
		CSRFToken:   csrf,
	}
	sessionsMu.Unlock()

	http.SetCookie(w, &http.Cookie{
		Name:     "session_id",
		Value:    sessionID,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
	})

	w.Header().Set("X-CSRF-Token", csrf)
	fmt.Fprintf(w, "{\"status\":\"ok\",\"permissions\":%d}", perms)
}

func adminHandler(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session_id")
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	sessionsMu.RLock()
	sess, exists := sessions[cookie.Value]
	sessionsMu.RUnlock()

	if !exists {
		http.Error(w, "Unauthorized", 401)
		return
	}

	// Verify CSRF for state-changing requests
	if r.Method != http.MethodGet {
		csrf := r.Header.Get("X-CSRF-Token")
		if !verifyCSRF(cookie.Value, csrf) {
			http.Error(w, "CSRF validation failed", 403)
			return
		}
	}

	// Check admin permission
	if sess.Permissions&PermAdmin == 0 {
		http.Error(w, "Forbidden: admin access required", 403)
		return
	}

	// Admin action: list all users
	rows, err := db.Query("SELECT id, username, base_permissions FROM users")
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var result strings.Builder
	result.WriteString("[")
	first := true
	for rows.Next() {
		var id int
		var uname string
		var perms uint8
		rows.Scan(&id, &uname, &perms)
		if !first {
			result.WriteString(",")
		}
		result.WriteString(fmt.Sprintf("{\"id\":%d,\"username\":%q,\"perms\":%d}", id, uname, perms))
		first = false
	}
	result.WriteString("]")

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(result.String()))
}

func deleteUserHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	cookie, err := r.Cookie("session_id")
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	sessionsMu.RLock()
	sess, exists := sessions[cookie.Value]
	sessionsMu.RUnlock()

	if !exists {
		http.Error(w, "Unauthorized", 401)
		return
	}

	csrf := r.Header.Get("X-CSRF-Token")
	if !verifyCSRF(cookie.Value, csrf) {
		http.Error(w, "CSRF validation failed", 403)
		return
	}

	if sess.Permissions&PermAdmin == 0 {
		http.Error(w, "Forbidden", 403)
		return
	}

	targetID, err := strconv.Atoi(r.FormValue("target_id"))
	if err != nil {
		http.Error(w, "Invalid target", 400)
		return
	}

	_, err = db.Exec("DELETE FROM users WHERE id = ?", targetID)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	fmt.Fprintf(w, "{\"deleted\":%d}", targetID)
}

func verifyPassword(password, hash string) bool {
	// In production, use bcrypt.CompareHashAndPassword
	h := sha256.Sum256([]byte(password))
	return hmac.Equal([]byte(hex.EncodeToString(h[:])), []byte(hash))
}

func setupDB() {
	var err error
	db, err = sql.Open("sqlite3", ":memory:")
	if err != nil {
		log.Fatal(err)
	}

	db.Exec(`CREATE TABLE users (
		id INTEGER PRIMARY KEY,
		username TEXT UNIQUE NOT NULL,
		password_hash TEXT NOT NULL,
		base_permissions INTEGER DEFAULT 1
	)`)

	db.Exec(`CREATE TABLE group_memberships (
		user_id INTEGER,
		group_id INTEGER,
		permission_bits INTEGER DEFAULT 0
	)`)

	db.Exec(`CREATE TABLE project_assignments (
		user_id INTEGER,
		project_id INTEGER,
		access_level INTEGER DEFAULT 0,
		active INTEGER DEFAULT 1
	)`)
}

func main() {
	setupDB()

	http.HandleFunc("/login", loginHandler)
	http.HandleFunc("/admin", adminHandler)
	http.HandleFunc("/admin/delete", deleteUserHandler)

	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
